#include "../Source/AnimationState.h"
#include <iostream>
#include <stdexcept>
void require(bool b,const char* why){if(!b)throw std::runtime_error(why);}
int main(){try{sauce::AnimationState s;s.setMode(2);s.recipeChanged();for(int i=0;i<12;i++)s.tick(.1f,.6f,.5f,1);require(s.lidLift()>.99f,"Lid opens");require(s.heldPeak==.5f,"Peak captured");for(int i=0;i<26;i++)s.tick(.1f,0,0,1);require(s.lidLift()==0,"Lid closes");require(s.heldPeak<.5f,"Peak decays after hold");s.tick(.05f,.7f,.7f,2);require(s.beat==1,"Transient lights coals");s.setMode(0);float time=s.time;s.recipeChanged();for(int i=0;i<100;i++)s.tick(.05f,.5f,.5f,3);require(s.time==time&&s.lidLift()==0&&s.beat==0,"Off stops decorations");require(s.needleDb>-7&&s.needleDb<-5,"Functional meter runs while off");s.setMode(1);require(s.intensity()>.3f&&s.intensity()<.4f,"Subtle intensity");s.setMode(2);require(s.intensity()==1,"Full intensity");for(int i=0;i<100000;i++)s.tick(.1f,i%2?4.f:0.f,i%7?0.f:4.f,i);require(std::isfinite(s.needleDb)&&s.needleDb>=-48&&s.needleDb<=6,"Meter stays bounded under stress");std::cout<<"PASS: motion modes, recipe lid, transients, peak hold, meter stability\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
